I1 = im2gray(imread('cameraman.tif'));
I2 = imrotate(I1, 20, 'bilinear', 'crop');
p1 = detectSURFFeatures(I1, 'MetricThreshold', 500);
p2 = detectSURFFeatures(I2, 'MetricThreshold', 500);
imshow(I1); hold on; plot(p1.selectStrongest(30));
fprintf('Found %d and %d points\n', p1.Count, p2.Count);

I = im2gray(imread('checkerboard.png'));
pts = detectHarrisFeatures(I, 'MinQuality', 0.05, 'FilterSize', 7);
imshow(I); hold on
plot(pts.selectStrongest(50));
fprintf('%d corners detected\n', pts.Count);

I1 = im2gray(imread('cameraman.tif'));
I2 = imresize(imrotate(I1, 30, 'bilinear', 'crop'), 0.8);
p1 = detectORBFeatures(I1, 'NumLevels', 8, 'ScaleFactor', 1.2);
p2 = detectORBFeatures(I2);
[f1, v1] = extractFeatures(I1, p1);
[f2, v2] = extractFeatures(I2, p2);
pairs = matchFeatures(f1, f2, 'MaxRatio', 0.7);
showMatchedFeatures(I1, I2, v1(pairs(:,1)), v2(pairs(:,2)), 'montage')

I = im2gray(imread('peppers.png'));
pts = detectSURFFeatures(I);
[feat, validPts] = extractFeatures(I, pts, 'Upright', false);
fprintf('%d descriptors of length %d\n', size(feat, 1), size(feat, 2));
fprintf('%d of %d points were valid\n', validPts.Count, pts.Count);

I1 = im2gray(imread('cameraman.tif'));
I2 = imtranslate(imrotate(I1, 12, 'bilinear', 'crop'), [15 -8]);
[f1, v1] = extractFeatures(I1, detectSURFFeatures(I1));
[f2, v2] = extractFeatures(I2, detectSURFFeatures(I2));
pairs = matchFeatures(f1, f2, 'MaxRatio', 0.6, 'Unique', true);
mp1 = v1(pairs(:,1)); mp2 = v2(pairs(:,2));
tform = estgeotform2d(mp2, mp1, 'similarity');
fprintf('%d matches\n', size(pairs, 1));

showMatchedFeatures(I1, I2, mp1, mp2, 'montage', ...
    'PlotOptions', {'ro','g+','y--'});
title('Putative matches');
[tform, inlierIdx] = estgeotform2d(mp2, mp1, 'similarity');
figure
showMatchedFeatures(I1, I2, mp1(inlierIdx), mp2(inlierIdx), 'montage');
title('Inlier matches');

[tform, inlierIdx, status] = estgeotform2d(mp2, mp1, 'projective', ...
    'MaxNumTrials', 3000, 'MaxDistance', 2, 'Confidence', 99.9);
if status == 0
    outputView = imref2d(size(I1));
    registered = imwarp(I2, tform, 'OutputView', outputView);
    imshowpair(I1, registered, 'falsecolor');
    fprintf('%d of %d matches were inliers\n', nnz(inlierIdx), numel(inlierIdx));
end

detector = vision.CascadeObjectDetector('FrontalFaceCART', ...
    'MinSize', [60 60], 'MergeThreshold', 6);
I = imread('visionteam.jpg');
bboxes = detector(I);
out = insertObjectAnnotation(I, 'rectangle', bboxes, 'face');
imshow(out)
fprintf('%d faces detected\n', size(bboxes, 1));

detector = yolov4ObjectDetector('tiny-yolov4-coco');
I = imread('highway.png');
[bboxes, scores, labels] = detect(detector, I, 'Threshold', 0.4);
out = insertObjectAnnotation(I, 'rectangle', bboxes, ...
    string(labels) + " " + round(scores, 2));
imshow(out)

data = load('vehicleTrainingData.mat');
tbl = data.vehicleTrainingData;
imds = imageDatastore(tbl.imageFilename);
