vr = VideoReader('visiontraffic.avi');
opticFlow = opticalFlowLK('NoiseThreshold', 0.009);
while hasFrame(vr)
    frame = im2gray(readFrame(vr));
    flow = estimateFlow(opticFlow, frame);
    imshow(frame); hold on
    plot(flow, 'DecimationFactor', [10 10], 'ScaleFactor', 20);
    hold off; drawnow
end

vr = VideoReader('visiontraffic.avi');
opticFlow = opticalFlowFarneback('NumPyramidLevels', 4, 'FilterSize', 21);
prev = im2gray(readFrame(vr));
estimateFlow(opticFlow, prev);
frame = im2gray(readFrame(vr));
flow = estimateFlow(opticFlow, frame);
imshow(flow.Magnitude, []); colorbar
title('Flow magnitude (pixels/frame)')

vr = VideoReader('visiontraffic.avi');
of = opticalFlowFarneback;
while hasFrame(vr)
    flow = estimateFlow(of, im2gray(readFrame(vr)));
    moving = flow.Magnitude > 1.5;
    imshow(moving); drawnow
end
reset(of);

